import {HardhatRuntimeEnvironment} from "hardhat/types";
import {AUSD, LiminalMarket, MarketCalendar, ServiceContract} from "../typechain-types";
import {LedgerSigner} from "@anders-t/ethers-ledger";
import {BigNumber} from "ethers";
import ContractAddresses from "./addresses/ContractAddresses";

export default class TaskHelper {
    hre: HardhatRuntimeEnvironment;

    static AddressZero = '0x0000000000000000000000000000000000000000';
    constructor(hre: HardhatRuntimeEnvironment) {
        this.hre = hre;
        console.log('network:', hre.network.name);
    }

    public async fundAUSD(contractAddress: string, amount = "1000000000000000000000", userWallet = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266") {
        console.log('aUSD address:' + contractAddress);

        const contract = await this.hre.ethers.getContractAt("aUSD", contractAddress) as AUSD;
        await contract.setBalance(userWallet, amount, 1);
        console.log('Funded ' + amount + ' to wallet ' + userWallet);
        let balance = await contract.balanceOf(userWallet);
        console.log('retrieved balance:' + balance)
    }

    public async setMarketCalendarAsOpen(contractAddress: string) {
        let opens = [new Date(((new Date().getTime() - (10 * 24 * 60 * 60 * 1000)) / 1000)).getTime(), new Date('Mar-20-2022').getTime()];
        let closes = [new Date(((new Date().getTime() + (10 * 24 * 60 * 60 * 1000)) / 1000)).getTime(), new Date('May-30-2022').getTime()];
        console.log('opens:' + new Date(opens[0]).getTime());
        console.log('closes:' + new Date(closes[0]).getTime());
        const contract = await this.hre.ethers.getContractAt("MarketCalendar", contractAddress) as MarketCalendar;
        await contract.setCalendar(opens, closes);
    }

    static GetSigner(hre: HardhatRuntimeEnvironment) {
        if (hre.network.name == 'localhost' || hre.network.name == 'hardhat' || hre.network.name == 'fuji') return hre.ethers.provider.getSigner();

        return hre.ethers.provider.getSigner();

        let signer = new LedgerSigner(hre.ethers.provider);
console.log(signer.path);
        return signer;

    }

    async executeTrade(contractAddress: ContractAddresses) {
        console.log('aUSD address:' + contractAddress);
        const lmContract = await this.hre.ethers.getContractAt("LiminalMarket", contractAddress.LIMINAL_MARKET_ADDRESS) as LiminalMarket;
let symbolAddress = await lmContract.getSecurityToken('MSFT')
        console.log('symbol:', symbolAddress)
        const aUsdContract = await this.hre.ethers.getContractAt("aUSD", contractAddress.AUSD_ADDRESS) as AUSD;
        await aUsdContract.transfer(symbolAddress, BigNumber.from('1' + '0'.repeat(18)))

        let app = await lmContract.attach(contractAddress.LIMINAL_MARKET_ADDRESS);
        const logs = await lmContract.filters.BuyWithAUsd();
    const _logs = await app.queryFilter(logs, 0)
        console.log(_logs);
    }

    async createToken(contractInfo: ContractAddresses) {
        const lmContract = await this.hre.ethers.getContractAt("LiminalMarket", contractInfo.LIMINAL_MARKET_ADDRESS) as LiminalMarket;
        await lmContract.createToken('MSFT')
    }

    async createServiceContract(contractInfo: ContractAddresses) {

        const serviceContract = await this.hre.ethers.getContractAt("ServiceContract", contractInfo.SERVICE_CONTRACT_ADDRESS) as ServiceContract;
        let feeAddress = await serviceContract.getServiceFeeAddress(contractInfo.LIMINAL_MARKET_ADDRESS)
        console.log('fee address:', feeAddress);
        if (feeAddress == TaskHelper.AddressZero) {
            console.log('create service contract')
            await serviceContract.createContract(contractInfo.LIMINAL_MARKET_ADDRESS, "0x8626f6940E2eb28930eFb4CeF49B2d1F2C9C1199", 100, "liminal.market", "liminal.market");
        }

        feeAddress = await serviceContract.getServiceFeeAddress(contractInfo.NO_FEE_CONTRACT_ADDRESS)
        console.log('fee address:', feeAddress);
        if (feeAddress == TaskHelper.AddressZero) {
            console.log('create service contract')
            await serviceContract.createContract(contractInfo.NO_FEE_CONTRACT_ADDRESS, "0x8626f6940E2eb28930eFb4CeF49B2d1F2C9C1199", 0, "liminal.market", "liminal.market");
        }
    }
}

